REPORT_SCRIPT='# Project Portfolio Overview v1.9 Verified Integration\r\n# Custom Script Report for Frappe / ERPNext 16 Safe Execution\r\n\r\nfilters = filters or {}\r\nview_mode = filters.get("view_mode") or "Executive"\r\n\r\nproject_meta = frappe.get_meta("Project")\r\n\r\ncommon_columns = [\r\n    {"label": _("Project"), "fieldname": "project", "fieldtype": "Link", "options": "Project", "width": 135},\r\n    {"label": _("Project Name"), "fieldname": "project_name", "fieldtype": "Data", "width": 240},\r\n    {"label": _("Stage"), "fieldname": "project_stage", "fieldtype": "Data", "width": 150},\r\n    {"label": _("Health"), "fieldname": "project_health", "fieldtype": "Data", "width": 105}\r\n]\r\n\r\ndonor_columns = [\r\n    {"label": _("Donor(s)"), "fieldname": "donor_display", "fieldtype": "Data", "width": 175},\r\n    {"label": _("Funding Status"), "fieldname": "funding_status", "fieldtype": "Data", "width": 135},\r\n    {"label": _("Sector(s)"), "fieldname": "sector_display", "fieldtype": "Data", "width": 155},\r\n    {"label": _("Implementation Location(s)"), "fieldname": "location_display", "fieldtype": "Data", "width": 220},\r\n    {"label": _("Start Date"), "fieldname": "start_date", "fieldtype": "Date", "width": 105},\r\n    {"label": _("End Date"), "fieldname": "end_date", "fieldtype": "Date", "width": 105},\r\n    {"label": _("Approved Funding"), "fieldname": "approved_funding", "fieldtype": "Currency", "options": "project_currency", "width": 145},\r\n    {"label": _("Implementation Budget"), "fieldname": "implementation_budget", "fieldtype": "Currency", "options": "project_currency", "width": 155},\r\n    {"label": _("Currency"), "fieldname": "project_currency", "fieldtype": "Link", "options": "Currency", "width": 85},\r\n    {"label": _("Activities Progress"), "fieldname": "activities_progress", "fieldtype": "Percent", "width": 120},\r\n    {"label": _("Indicator Achievement"), "fieldname": "indicator_achievement", "fieldtype": "Percent", "width": 130},\r\n    {"label": _("Time Elapsed"), "fieldname": "time_elapsed", "fieldtype": "Percent", "width": 105},\r\n    {"label": _("Planned Individuals"), "fieldname": "planned_individuals", "fieldtype": "Int", "width": 130},\r\n    {"label": _("Actual Individuals"), "fieldname": "actual_individuals", "fieldtype": "Int", "width": 125},\r\n    {"label": _("Planned Households"), "fieldname": "planned_households", "fieldtype": "Int", "width": 135},\r\n    {"label": _("Actual Households"), "fieldname": "actual_households", "fieldtype": "Int", "width": 130}\r\n]\r\n\r\noperations_columns = [\r\n    {"label": _("Project Manager"), "fieldname": "project_manager", "fieldtype": "Link", "options": "Employee", "width": 145},\r\n    {"label": _("Status"), "fieldname": "status", "fieldtype": "Data", "width": 95},\r\n    {"label": _("Implementation Modality"), "fieldname": "implementation_modality", "fieldtype": "Data", "width": 155},\r\n    {"label": _("Implementing Partners"), "fieldname": "implementing_partners", "fieldtype": "Data", "width": 190},\r\n    {"label": _("Partners"), "fieldname": "partner_count", "fieldtype": "Int", "width": 80},\r\n    {"label": _("Completed Activities"), "fieldname": "completed_activities", "fieldtype": "Int", "width": 135},\r\n    {"label": _("Delayed Activities"), "fieldname": "delayed_activities", "fieldtype": "Int", "width": 125},\r\n    {"label": _("Critical Risks"), "fieldname": "critical_risks", "fieldtype": "Int", "width": 105},\r\n    {"label": _("Critical Issues"), "fieldname": "critical_issues", "fieldtype": "Int", "width": 105},\r\n    {"label": _("Open Change Requests"), "fieldname": "open_changes", "fieldtype": "Int", "width": 135},\r\n    {"label": _("Overdue Deliverables"), "fieldname": "overdue_deliverables", "fieldtype": "Int", "width": 135},\r\n    {"label": _("Last Progress Update"), "fieldname": "last_update", "fieldtype": "Date", "width": 125},\r\n    {"label": _("Update Status"), "fieldname": "update_status", "fieldtype": "Data", "width": 120},\r\n    {"label": _("Management Attention"), "fieldname": "attention", "fieldtype": "Data", "width": 250}\r\n]\r\n\r\nif view_mode == "Donor":\r\n    columns = common_columns + donor_columns\r\nelif view_mode == "Operations":\r\n    columns = common_columns + operations_columns\r\nelif view_mode == "Full":\r\n    columns = common_columns + donor_columns + operations_columns\r\nelse:\r\n    columns = common_columns + [\r\n        donor_columns[0], donor_columns[2], donor_columns[3], donor_columns[4],\r\n        donor_columns[5], donor_columns[7], donor_columns[9], donor_columns[10],\r\n        donor_columns[12], donor_columns[13]\r\n    ] + [\r\n        operations_columns[6], operations_columns[7], operations_columns[8],\r\n        operations_columns[9], operations_columns[11], operations_columns[12],\r\n        operations_columns[13]\r\n    ]\r\n\r\nproject_fields = [\r\n    "name", "project_name", "status", "is_active", "company",\r\n    "expected_start_date", "expected_end_date", "percent_complete"\r\n]\r\noptional_project_fields = [\r\n    "custom_project_stage", "custom_calculated_project_health", "custom_project_health",\r\n    "custom_funding_status", "custom_implementation_modality", "custom_project_manager",\r\n    "custom_project_currency", "custom_approved_funding_amount",\r\n    "custom_current_implementation_budget", "custom_activities_progress_percentage",\r\n    "custom_indicators_achievement_percentage", "custom_time_elapsed_percentage",\r\n    "custom_completed_activities", "custom_delayed_activities",\r\n    "custom_latest_progress_update_date", "custom_progress_update_monitoring_status",\r\n    "custom_planned_individuals", "custom_actual_individuals",\r\n    "custom_planned_households", "custom_actual_households",\r\n    "custom_beneficiary_plan_status"\r\n]\r\nfor fieldname in optional_project_fields:\r\n    if project_meta.has_field(fieldname):\r\n        project_fields.append(fieldname)\r\n\r\nproject_filters = {}\r\nproject_values = filters.get("project") or []\r\nif project_values:\r\n    project_filters["name"] = ["in", project_values]\r\ncompany_values = filters.get("company") or []\r\nif company_values:\r\n    project_filters["company"] = ["in", company_values]\r\nimplementation_modality_values = filters.get("implementation_modality") or []\r\nif implementation_modality_values and project_meta.has_field("custom_implementation_modality"):\r\n    project_filters["custom_implementation_modality"] = ["in", implementation_modality_values]\r\nproject_currency_values = filters.get("project_currency") or []\r\nif project_currency_values and project_meta.has_field("custom_project_currency"):\r\n    project_filters["custom_project_currency"] = ["in", project_currency_values]\r\nproject_stage_values = filters.get("project_stage") or []\r\nif project_stage_values and project_meta.has_field("custom_project_stage"):\r\n    project_filters["custom_project_stage"] = ["in", project_stage_values]\r\nfunding_status_values = filters.get("funding_status") or []\r\nif funding_status_values and project_meta.has_field("custom_funding_status"):\r\n    project_filters["custom_funding_status"] = ["in", funding_status_values]\r\nproject_health_values = filters.get("project_health") or []\r\nif project_health_values and project_meta.has_field("custom_calculated_project_health"):\r\n    project_filters["custom_calculated_project_health"] = ["in", project_health_values]\r\nif int(filters.get("active_only") or 0) == 1:\r\n    project_filters["is_active"] = "Yes"\r\nif int(filters.get("include_closed") or 0) != 1 and project_meta.has_field("custom_project_stage"):\r\n    if project_stage_values:\r\n        open_stage_values = []\r\n        for stage_value in project_stage_values:\r\n            if stage_value not in ["Closed", "Cancelled", "Rejected"]:\r\n                open_stage_values.append(stage_value)\r\n        project_filters["custom_project_stage"] = ["in", open_stage_values] if open_stage_values else ["in", ["__none__"]]\r\n    else:\r\n        project_filters["custom_project_stage"] = ["not in", ["Closed", "Cancelled", "Rejected"]]\r\nproject_manager_values = filters.get("project_manager") or []\r\nif project_manager_values and project_meta.has_field("custom_project_manager"):\r\n    project_filters["custom_project_manager"] = ["in", project_manager_values]\r\n\r\nprojects = frappe.get_all(\r\n    "Project",\r\n    filters=project_filters,\r\n    fields=project_fields,\r\n    order_by="expected_end_date asc, project_name asc",\r\n    limit_page_length=0\r\n)\r\n\r\nrows = []\r\nfor project in projects:\r\n    start_date = str(project.get("expected_start_date") or "")\r\n    end_date = str(project.get("expected_end_date") or "")\r\n    from_date = str(filters.get("from_date") or "")\r\n    to_date = str(filters.get("to_date") or "")\r\n    if from_date and end_date and end_date < from_date:\r\n        continue\r\n    if to_date and start_date and start_date > to_date:\r\n        continue\r\n\r\n    project_name = project.get("name")\r\n    donor_display_mode = filters.get("donor_display_mode") or "Primary"\r\n    sector_display_mode = filters.get("sector_display_mode") or "Primary"\r\n    partner_display_mode = filters.get("partner_display_mode") or "All"\r\n    location_display_mode = filters.get("location_display_mode") or "Primary"\r\n\r\n    primary_donor = ""\r\n    funding_rows = frappe.get_all(\r\n        "Project Funding Source",\r\n        filters={"parent": project_name, "parenttype": "Project"},\r\n        fields=["donor", "is_primary_donor", "funding_status", "approved_amount_project_currency"],\r\n        order_by="idx asc",\r\n        limit_page_length=0\r\n    )\r\n    for funding_row in funding_rows:\r\n        if int(funding_row.get("is_primary_donor") or 0) == 1:\r\n            primary_donor = funding_row.get("donor") or ""\r\n            break\r\n    if not primary_donor and funding_rows:\r\n        primary_donor = funding_rows[0].get("donor") or ""\r\n    donor_names = []\r\n    for funding_row in funding_rows:\r\n        donor_name = funding_row.get("donor") or ""\r\n        if donor_name and donor_name not in donor_names:\r\n            donor_names.append(donor_name)\r\n    donor_values = filters.get("donor") or []\r\n    if donor_values:\r\n        donor_match = False\r\n        for donor_value in donor_values:\r\n            if donor_value in donor_names:\r\n                donor_match = True\r\n        if not donor_match:\r\n            continue\r\n\r\n    primary_sector = ""\r\n    sector_rows = frappe.get_all(\r\n        "Project Sector",\r\n        filters={"parent": project_name, "parenttype": "Project"},\r\n        fields=["sector", "is_primary_sector"],\r\n        order_by="idx asc",\r\n        limit_page_length=0\r\n    )\r\n    for sector_row in sector_rows:\r\n        if int(sector_row.get("is_primary_sector") or 0) == 1:\r\n            primary_sector = sector_row.get("sector") or ""\r\n            break\r\n    if not primary_sector and sector_rows:\r\n        primary_sector = sector_rows[0].get("sector") or ""\r\n    sector_names = []\r\n    for sector_row in sector_rows:\r\n        sector_name = sector_row.get("sector") or ""\r\n        if sector_name and sector_name not in sector_names:\r\n            sector_names.append(sector_name)\r\n    sector_values = filters.get("sector") or []\r\n    if sector_values:\r\n        sector_match = False\r\n        for sector_value in sector_values:\r\n            if sector_value in sector_names:\r\n                sector_match = True\r\n        if not sector_match:\r\n            continue\r\n\r\n    governorate = ""\r\n    district = ""\r\n    location_rows = frappe.get_all(\r\n        "Project Geographic Location",\r\n        filters={"parent": project_name, "parenttype": "Project"},\r\n        fields=["governorate", "district", "is_primary_location"],\r\n        order_by="idx asc",\r\n        limit_page_length=0\r\n    )\r\n    selected_location = None\r\n    for location_row in location_rows:\r\n        if int(location_row.get("is_primary_location") or 0) == 1:\r\n            selected_location = location_row\r\n            break\r\n    if not selected_location and location_rows:\r\n        selected_location = location_rows[0]\r\n    if selected_location:\r\n        governorate = selected_location.get("governorate") or ""\r\n        district = selected_location.get("district") or ""\r\n    governorate_names = []\r\n    district_names = []\r\n    for location_row in location_rows:\r\n        governorate_name = location_row.get("governorate") or ""\r\n        district_name = location_row.get("district") or ""\r\n        if governorate_name and governorate_name not in governorate_names:\r\n            governorate_names.append(governorate_name)\r\n        if district_name and district_name not in district_names:\r\n            district_names.append(district_name)\r\n    governorate_values = filters.get("governorate") or []\r\n    if governorate_values:\r\n        governorate_match = False\r\n        for governorate_value in governorate_values:\r\n            if governorate_value in governorate_names:\r\n                governorate_match = True\r\n        if not governorate_match:\r\n            continue\r\n    district_values = filters.get("district") or []\r\n    if district_values:\r\n        district_match = False\r\n        for district_value in district_values:\r\n            if district_value in district_names:\r\n                district_match = True\r\n        if not district_match:\r\n            continue\r\n\r\n    donor_display = primary_donor if donor_display_mode == "Primary" else ", ".join(donor_names)\r\n    sector_display = primary_sector if sector_display_mode == "Primary" else ", ".join(sector_names)\r\n    location_display_values = []\r\n    for location_row in location_rows:\r\n        location_text = " - ".join([value for value in [location_row.get("governorate") or "", location_row.get("district") or ""] if value])\r\n        if location_text and location_text not in location_display_values:\r\n            location_display_values.append(location_text)\r\n    primary_location_display = " - ".join([value for value in [governorate, district] if value])\r\n    location_display = primary_location_display if location_display_mode == "Primary" else ", ".join(location_display_values)\r\n\r\n    derived_funding_status = project.get("custom_funding_status") or ""\r\n    if not derived_funding_status:\r\n        funding_status_list = []\r\n        for funding_row in funding_rows:\r\n            funding_row_status = funding_row.get("funding_status") or ""\r\n            if funding_row_status and funding_row_status not in funding_status_list:\r\n                funding_status_list.append(funding_row_status)\r\n        if "Approved" in funding_status_list:\r\n            derived_funding_status = "Approved"\r\n        elif "Partially Approved" in funding_status_list:\r\n            derived_funding_status = "Partially Approved"\r\n        elif funding_status_list:\r\n            derived_funding_status = funding_status_list[0]\r\n\r\n    critical_risks = len(frappe.get_all(\r\n        "Project Risk",\r\n        filters={\r\n            "project": project_name,\r\n            "status": ["not in", ["Closed", "Inactive"]],\r\n            "residual_risk_level": "Critical"\r\n        },\r\n        fields=["name"],\r\n        limit_page_length=0\r\n    ))\r\n\r\n    critical_issues = len(frappe.get_all(\r\n        "Issue",\r\n        filters={\r\n            "project": project_name,\r\n            "status": ["not in", ["Resolved", "Closed", "Cancelled"]],\r\n            "custom_project_issue_severity": "Critical"\r\n        },\r\n        fields=["name"],\r\n        limit_page_length=0\r\n    ))\r\n\r\n    open_changes = len(frappe.get_all(\r\n        "Project Change Request",\r\n        filters={\r\n            "project": project_name,\r\n            "docstatus": 1,\r\n            "implementation_status": ["in", ["Not Started", "In Progress", "Implementation Failed"]]\r\n        },\r\n        fields=["name"],\r\n        limit_page_length=0\r\n    ))\r\n\r\n    overdue_deliverables = 0\r\n    if frappe.db.exists("DocType", "Project Compliance Deliverable"):\r\n        compliance_meta = frappe.get_meta("Project Compliance Deliverable")\r\n        due_field = "submission_due_date" if compliance_meta.has_field("submission_due_date") else ""\r\n        state_field = "workflow_state" if compliance_meta.has_field("workflow_state") else "status"\r\n        if due_field and compliance_meta.has_field(state_field):\r\n            overdue_deliverables = len(frappe.get_all(\r\n                "Project Compliance Deliverable",\r\n                filters={\r\n                    "project": project_name,\r\n                    due_field: ["<", frappe.utils.nowdate()],\r\n                    state_field: ["not in", ["Approved", "Waived", "Rejected", "Cancelled"]]\r\n                },\r\n                fields=["name"],\r\n                limit_page_length=0\r\n            ))\r\n\r\n    partner_rows = frappe.get_all(\r\n        "Project Partner",\r\n        filters={"parent": project_name, "parenttype": "Project"},\r\n        fields=["partner", "is_lead_partner"],\r\n        order_by="idx asc",\r\n        limit_page_length=0\r\n    )\r\n    partner_count = len(partner_rows)\r\n    partner_names = []\r\n    for partner_row in partner_rows:\r\n        partner_name = partner_row.get("partner") or ""\r\n        if partner_name and partner_name not in partner_names:\r\n            partner_names.append(partner_name)\r\n    implementing_partners = ", ".join(partner_names)\r\n    lead_partner = ""\r\n    for partner_row in partner_rows:\r\n        if int(partner_row.get("is_lead_partner") or 0) == 1:\r\n            lead_partner = partner_row.get("partner") or ""\r\n            break\r\n    if not lead_partner and partner_names:\r\n        lead_partner = partner_names[0]\r\n    partner_display = lead_partner if partner_display_mode == "Primary" else implementing_partners\r\n    implementing_partner_values = filters.get("implementing_partner") or []\r\n    if implementing_partner_values:\r\n        partner_match = False\r\n        for implementing_partner_value in implementing_partner_values:\r\n            if implementing_partner_value in partner_names:\r\n                partner_match = True\r\n        if not partner_match:\r\n            continue\r\n\r\n    latest_progress_update = None\r\n    if frappe.db.exists("DocType", "Project Progress Update"):\r\n        approved_updates = frappe.get_all(\r\n            "Project Progress Update",\r\n            filters={"project": project_name, "status": "Approved"},\r\n            fields=["name", "cutoff_date", "period_end_date", "approved_on"],\r\n            order_by="period_end_date desc, approved_on desc, modified desc",\r\n            limit=1\r\n        )\r\n        if approved_updates:\r\n            latest_progress_update = approved_updates[0]\r\n\r\n    project_health = (\r\n        project.get("custom_calculated_project_health")\r\n        or project.get("custom_project_health")\r\n        or "Not Assessed"\r\n    )\r\n    completed_activities = int(project.get("custom_completed_activities") or 0)\r\n    delayed_activities = int(project.get("custom_delayed_activities") or 0)\r\n    if frappe.db.exists("DocType", "Project Workplan Activity"):\r\n        activity_meta = frappe.get_meta("Project Workplan Activity")\r\n        activity_status_field = "status" if activity_meta.has_field("status") else ("activity_status" if activity_meta.has_field("activity_status") else "")\r\n        activity_monitoring_field = "monitoring_status" if activity_meta.has_field("monitoring_status") else ""\r\n        activity_fields = ["name"]\r\n        if activity_status_field:\r\n            activity_fields.append(activity_status_field)\r\n        if activity_monitoring_field:\r\n            activity_fields.append(activity_monitoring_field)\r\n        activity_rows = frappe.get_all("Project Workplan Activity", filters={"project": project_name}, fields=activity_fields, limit_page_length=0)\r\n        if activity_rows:\r\n            completed_count = 0\r\n            delayed_count = 0\r\n            for activity_row in activity_rows:\r\n                activity_status = activity_row.get(activity_status_field) or "" if activity_status_field else ""\r\n                activity_monitoring = activity_row.get(activity_monitoring_field) or "" if activity_monitoring_field else ""\r\n                if activity_status in ["Completed", "Complete"]:\r\n                    completed_count += 1\r\n                if activity_status in ["Delayed", "Overdue", "Behind Schedule"] or activity_monitoring in ["Overdue", "Critical", "Delayed"]:\r\n                    delayed_count += 1\r\n            completed_activities = completed_count\r\n            delayed_activities = delayed_count\r\n    update_status = project.get("custom_progress_update_monitoring_status") or ""\r\n\r\n    attention_items = []\r\n    if project_health in ["At Risk", "Critical", "On Hold"]:\r\n        attention_items.append(str(project_health))\r\n    if delayed_activities:\r\n        attention_items.append(str(delayed_activities) + " delayed activities")\r\n    if critical_risks:\r\n        attention_items.append(str(critical_risks) + " critical risks")\r\n    if critical_issues:\r\n        attention_items.append(str(critical_issues) + " critical issues")\r\n    if open_changes:\r\n        attention_items.append(str(open_changes) + " open change requests")\r\n    if overdue_deliverables:\r\n        attention_items.append(str(overdue_deliverables) + " overdue deliverables")\r\n    if update_status in ["Overdue", "Critical", "Update Required"]:\r\n        attention_items.append("progress update " + str(update_status))\r\n\r\n    project_manager = project.get("custom_project_manager") or ""\r\n    project_manager_name = ""\r\n    if project_manager:\r\n        project_manager_name = frappe.db.get_value("Employee", project_manager, "employee_name") or project_manager\r\n\r\n    location_pairs = []\r\n    for location_row in location_rows:\r\n        pair_governorate = location_row.get("governorate") or ""\r\n        pair_district = location_row.get("district") or ""\r\n        pair_value = pair_governorate + "|||" + pair_district\r\n        if pair_value not in location_pairs:\r\n            location_pairs.append(pair_value)\r\n\r\n    row = {\r\n        "project": project_name,\r\n        "project_name": project.get("project_name"),\r\n        "project_stage": project.get("custom_project_stage") or project.get("status"),\r\n        "project_health": project_health,\r\n        "status": project.get("status"),\r\n        "project_manager": project_manager,\r\n        "project_manager_name": project_manager_name,\r\n        "all_donors": "|||".join(donor_names),\r\n        "all_sectors": "|||".join(sector_names),\r\n        "all_partners": "|||".join(partner_names),\r\n        "all_governorates": "|||".join(governorate_names),\r\n        "all_districts": "|||".join(district_names),\r\n        "location_pairs": ";;;".join(location_pairs),\r\n        "primary_donor": primary_donor,\r\n        "donor_display": donor_display,\r\n        "funding_status": derived_funding_status,\r\n        "primary_sector": primary_sector,\r\n        "sector_display": sector_display,\r\n        "governorate": governorate,\r\n        "district": district,\r\n        "location_display": location_display,\r\n        "start_date": project.get("expected_start_date"),\r\n        "end_date": project.get("expected_end_date"),\r\n        "approved_funding": float(project.get("custom_approved_funding_amount") or 0),\r\n        "implementation_budget": float(project.get("custom_current_implementation_budget") or 0),\r\n        "project_currency": project.get("custom_project_currency"),\r\n        "implementation_modality": project.get("custom_implementation_modality"),\r\n        "activities_progress": float(project.get("custom_activities_progress_percentage") or project.get("percent_complete") or 0),\r\n        "indicator_achievement": float(project.get("custom_indicators_achievement_percentage") or 0),\r\n        "time_elapsed": float(project.get("custom_time_elapsed_percentage") or 0),\r\n        "planned_individuals": int(project.get("custom_planned_individuals") or 0),\r\n        "actual_individuals": int(project.get("custom_actual_individuals") or 0),\r\n        "planned_households": int(project.get("custom_planned_households") or 0),\r\n        "actual_households": int(project.get("custom_actual_households") or 0),\r\n        "partner_count": partner_count,\r\n        "implementing_partners": implementing_partners,\r\n        "partner_display": partner_display,\r\n        "completed_activities": completed_activities,\r\n        "delayed_activities": delayed_activities,\r\n        "critical_risks": critical_risks,\r\n        "critical_issues": critical_issues,\r\n        "open_changes": open_changes,\r\n        "overdue_deliverables": overdue_deliverables,\r\n        "last_update": (latest_progress_update.get("cutoff_date") or latest_progress_update.get("period_end_date") or latest_progress_update.get("approved_on")) if latest_progress_update else project.get("custom_latest_progress_update_date"),\r\n        "update_status": update_status,\r\n        "attention": "; ".join(attention_items)\r\n    }\r\n\r\n    attention_rank = 0\r\n    if project_health == "Critical":\r\n        attention_rank = 100\r\n    elif project_health == "At Risk":\r\n        attention_rank = 80\r\n    elif project_health == "On Hold":\r\n        attention_rank = 70\r\n    attention_rank += critical_risks * 10\r\n    attention_rank += critical_issues * 10\r\n    attention_rank += overdue_deliverables * 5\r\n    attention_rank += delayed_activities * 3\r\n    attention_rank += open_changes * 2\r\n    if update_status == "Critical":\r\n        attention_rank += 20\r\n    elif update_status in ["Overdue", "Update Required"]:\r\n        attention_rank += 10\r\n    row["attention_rank"] = attention_rank\r\n\r\n    if int(filters.get("attention_only") or 0) == 1 and not row.get("attention"):\r\n        continue\r\n    rows.append(row)\r\n\r\n# Management-first sorting without custom functions keeps Safe Execution compatibility.\r\npriority_rows = []\r\nnormal_rows = []\r\nfor portfolio_row in rows:\r\n    if int(portfolio_row.get("attention_rank") or 0) > 0:\r\n        priority_rows.append(portfolio_row)\r\n    else:\r\n        normal_rows.append(portfolio_row)\r\nranked_priority_rows = []\r\nfor rank_value in [200, 150, 120, 100, 80, 70, 50, 30, 10, 1]:\r\n    for priority_row in priority_rows:\r\n        row_rank = int(priority_row.get("attention_rank") or 0)\r\n        if row_rank >= rank_value and priority_row not in ranked_priority_rows:\r\n            ranked_priority_rows.append(priority_row)\r\npriority_rows = ranked_priority_rows\r\nrows = priority_rows + normal_rows\r\n\r\ntotal_projects = len(rows)\r\nactive_projects = 0\r\nunder_implementation = 0\r\nattention_projects = 0\r\ncritical_projects = 0\r\nplanned_individuals = 0\r\nactual_individuals = 0\r\ncurrencies = []\r\nimplementation_budget = 0.0\r\ntotal_activity_progress = 0.0\r\ntotal_indicator_progress = 0.0\r\nactivity_progress_count = 0\r\nindicator_progress_count = 0\r\ntotal_delayed_activities = 0\r\ntotal_critical_risks = 0\r\ntotal_critical_issues = 0\r\n\r\nfor row in rows:\r\n    if row.get("project_stage") not in ["Closed", "Cancelled", "Rejected"]:\r\n        active_projects += 1\r\n    if row.get("project_stage") == "Under Implementation":\r\n        under_implementation += 1\r\n    if row.get("attention"):\r\n        attention_projects += 1\r\n    if row.get("project_health") == "Critical":\r\n        critical_projects += 1\r\n    activity_value = float(row.get("activities_progress") or 0)\r\n    indicator_value = float(row.get("indicator_achievement") or 0)\r\n    total_activity_progress += activity_value\r\n    activity_progress_count += 1\r\n    total_indicator_progress += indicator_value\r\n    indicator_progress_count += 1\r\n    total_delayed_activities += int(row.get("delayed_activities") or 0)\r\n    total_critical_risks += int(row.get("critical_risks") or 0)\r\n    total_critical_issues += int(row.get("critical_issues") or 0)\r\n    planned_individuals += int(row.get("planned_individuals") or 0)\r\n    actual_individuals += int(row.get("actual_individuals") or 0)\r\n    implementation_budget += float(row.get("implementation_budget") or 0)\r\n    currency = row.get("project_currency") or ""\r\n    if currency and currency not in currencies:\r\n        currencies.append(currency)\r\n\r\naverage_activity_progress = (\r\n    total_activity_progress / activity_progress_count if activity_progress_count else 0\r\n)\r\naverage_indicator_progress = (\r\n    total_indicator_progress / indicator_progress_count if indicator_progress_count else 0\r\n)\r\n\r\nreport_summary = [\r\n    {"value": total_projects, "indicator": "Blue", "label": _("Projects"), "datatype": "Int"},\r\n    {"value": active_projects, "indicator": "Green", "label": _("Active"), "datatype": "Int"},\r\n    {"value": under_implementation, "indicator": "Blue", "label": _("Under Implementation"), "datatype": "Int"},\r\n    {"value": attention_projects, "indicator": "Red" if attention_projects else "Green", "label": _("Need Attention"), "datatype": "Int"},\r\n    {"value": critical_projects, "indicator": "Red" if critical_projects else "Green", "label": _("Critical Projects"), "datatype": "Int"},\r\n    {"value": total_delayed_activities, "indicator": "Orange" if total_delayed_activities else "Green", "label": _("Delayed Activities"), "datatype": "Int"}\r\n]\r\n\r\nif average_activity_progress > 0:\r\n    report_summary.append({"value": round(average_activity_progress, 1), "indicator": "Blue", "label": _("Average Activity Progress"), "datatype": "Percent"})\r\nif average_indicator_progress > 0:\r\n    report_summary.append({"value": round(average_indicator_progress, 1), "indicator": "Blue", "label": _("Average Indicator Achievement"), "datatype": "Percent"})\r\nif planned_individuals > 0 or actual_individuals > 0:\r\n    report_summary.append({"value": planned_individuals, "indicator": "Blue", "label": _("Planned Individuals"), "datatype": "Int"})\r\n    report_summary.append({"value": actual_individuals, "indicator": "Green", "label": _("Actual Individuals"), "datatype": "Int"})\r\nif len(currencies) == 1 and implementation_budget > 0:\r\n    report_summary.append({\r\n        "value": implementation_budget,\r\n        "indicator": "Blue",\r\n        "label": _("Implementation Budget") + " (" + currencies[0] + ")",\r\n        "datatype": "Currency",\r\n        "currency": currencies[0]\r\n    })\r\n\r\nchart_by = filters.get("chart_by") or "Stage"\r\nchart_field = "project_stage"\r\nif chart_by == "Health":\r\n    chart_field = "project_health"\r\nelif chart_by == "Sector":\r\n    chart_field = "primary_sector"\r\nelif chart_by == "Governorate":\r\n    chart_field = "governorate"\r\nelif chart_by == "Donor":\r\n    chart_field = "primary_donor"\r\n\r\nchart_counts = {}\r\nfor row in rows:\r\n    chart_key = row.get(chart_field) or _("Not Specified")\r\n    chart_counts[chart_key] = chart_counts.get(chart_key, 0) + 1\r\n\r\nchart_labels = []\r\nchart_values = []\r\nfor chart_key in chart_counts:\r\n    chart_labels.append(chart_key)\r\n    chart_values.append(chart_counts[chart_key])\r\n\r\nchart = {\r\n    "data": {\r\n        "labels": chart_labels,\r\n        "datasets": [{"name": _("Projects"), "values": chart_values}]\r\n    },\r\n    "type": "donut" if chart_by == "Health" else "bar",\r\n    "height": 320,\r\n    "colors": ["#1565C0", "#2E7D32", "#F9A825", "#C62828", "#6A1B9A", "#00838F"]\r\n}\r\n\r\nmessage = ""\r\nif not rows:\r\n    message = _("No projects match the selected filters.")\r\nelif len(currencies) > 1:\r\n    message = _("The portfolio contains multiple currencies. Monetary totals are intentionally excluded from the summary cards.")\r\n\r\n# Custom Script Report output\r\ndata = (columns, rows, message, chart, report_summary, 1)\r\n'
def _apply_native_sticky(result):
    if not result:
        return result
    values = list(result) if isinstance(result, (tuple, list)) else [result]
    if not values:
        return result
    columns = values[0] or []
    for index, column in enumerate(columns):
        if isinstance(column, dict):
            column["sticky"] = bool(index < 2)
    values[0] = columns
    return tuple(values)

def execute(filters=None):
    local_vars={"filters":filters or {}}
    safe_exec(REPORT_SCRIPT,None,local_vars,script_filename='Project Portfolio Overview')
    return finalize_report_result(local_vars.get("data") or ([], []))
